<script setup>
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue'
import {useI18n} from 'vue-i18n'
import ProfileEditor from './ProfileEditor.vue'
import {defaultProfile,layoutProfile} from './layout-profile.js'
import {themeStyle} from './themes.js'
import {targetsFor,pairingUrl,errorKey,importLayout} from './admin-client.js'
import {persist} from './locale-core.js'
const {t,locale}=useI18n()
const session=ref(null),secret=ref(''),busy=ref(false),error=ref(''),notice=ref(''),devices=ref([]),nextBefore=ref(null),selected=ref([]),filter=ref('active'),search=ref(''),events=ref([])
const newName=ref(''),days=ref(30),grants=ref(['codex','system','github','rss','weather']),providers=['codex','system','github','rss','weather','tasks','chatgpt']
const draft=ref({...defaultProfile}),pair=ref(null),canvas=ref(null),creating=ref(false),editing=ref(null),editName=ref(''),policyText=ref(''),revokeId=ref(null),profileJson=ref('')
const secure=location.protocol==='https:'
let pairTimer,disposed=false
const visible=computed(()=>devices.value.filter(d=>(filter.value==='all'||d.status===filter.value)&&`${d.name} ${d.id}`.toLowerCase().includes(search.value.toLowerCase())))
const targets=computed(()=>targetsFor(devices.value,selected.value))
const style=computed(()=>themeStyle({...defaultProfile,theme:'paper',accent:'blue'},false))
function forgetPair(){clearTimeout(pairTimer);pair.value=null}
function clearSession(){session.value=null;devices.value=[];selected.value=[];events.value=[];editing.value=null;forgetPair()}
async function api(path,method='GET',body,token){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000)
 try{
  const headers={};if(body!==undefined)headers['Content-Type']='application/json';if(token)headers.Authorization='Bearer '+token
  const response=await fetch('/api/admin'+path,{method,credentials:'same-origin',cache:'no-store',headers,body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal})
  if(!response.ok){if(response.status===401)clearSession();const e=new Error(errorKey(response.status));e.status=response.status;throw e}
  return response.status===204?null:await response.json()
 }finally{clearTimeout(timer)}
}
async function run(action){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e.message?.startsWith('admin.')?e.message:'admin.failed'}finally{busy.value=false}}
async function load(more=false){const result=await api('/devices'+(more&&nextBefore.value?'?before='+encodeURIComponent(nextBefore.value):''));if(disposed)return;devices.value=more?[...devices.value,...result.devices]:result.devices;nextBefore.value=result.next_before;selected.value=selected.value.filter(id=>devices.value.some(d=>d.id===id&&d.status==='active'&&!d.configuration_error))}
function login(){run(async()=>{const key=secret.value;secret.value='';session.value=await api('/session','POST',undefined,key);await load()})}
function logout(){run(async()=>{await api('/session','DELETE');clearSession();notice.value='admin.signedOut'})}
function refresh(){run(()=>load())}
function useProfile(device){draft.value=layoutProfile(device.profile);profileJson.value='';notice.value='admin.loaded'}
function importProfile(){try{draft.value=importLayout(profileJson.value);notice.value='admin.imported';error.value=''}catch{error.value='admin.invalid'}}
function publish(){run(async()=>{if(!targets.value.length||targets.value.length>20)return;await api('/profiles/publish','POST',{targets:targets.value,profile:draft.value});await load();notice.value='admin.published'})}
function create(){run(async()=>{
 forgetPair();const result=await api('/devices','POST',{name:newName.value,providers:grants.value,days:days.value,profile:draft.value})
 if(!document.hidden)pair.value={id:result.id,expires_at:result.expires_at,url:pairingUrl(location.origin,result.token)}
 creating.value=false;newName.value='';await nextTick()
 const QR=await import('qrcode');if(pair.value&&canvas.value)await QR.default.toCanvas(canvas.value,pair.value.url,{width:256,margin:4,errorCorrectionLevel:'M'})
 pairTimer=setTimeout(forgetPair,600000);await load();notice.value='admin.created'
})}
function edit(device){editing.value=device;editName.value=device.name;policyText.value=JSON.stringify(device.policy,null,2);revokeId.value=null}
function saveDevice(){run(async()=>{let policy;try{if(policyText.value.length>16000)throw Error();policy=JSON.parse(policyText.value)}catch{throw Error('admin.invalid')}
 await api('/devices/'+editing.value.id+'/configure','POST',{revision:editing.value.revision,name:editName.value,policy});editing.value=null;await load();notice.value='admin.saved'
})}
function revoke(device){run(async()=>{await api('/devices/'+device.id+'/revoke','POST');if(pair.value?.id===device.id)forgetPair();revokeId.value=null;await load();notice.value='admin.revokedNotice'})}
function history(){run(async()=>{events.value=(await api('/audit')).events})}
function language(){try{persist(localStorage,'pixora-locale',locale.value)}catch{}document.documentElement.lang=locale.value}
function hide(){if(document.hidden){forgetPair();secret.value=''}}
onMounted(()=>{document.addEventListener('visibilitychange',hide);run(async()=>{try{session.value=await api('/session')}catch(e){if(e.status===401){error.value='';return}throw e}await load()})})
onUnmounted(()=>{disposed=true;forgetPair();secret.value='';document.removeEventListener('visibilitychange',hide)})
</script>
<template><div class="pixora-themed preset-paper appearance-light" :style="style"><main class="admin-page" data-ui><header class="app-bar"><div class="brand-lockup"><span>Pixora</span><small>{{t('admin.title')}}</small></div><div class="actions"><label class="language"><span class="sr-only">{{t('config.language')}}</span><select v-model="locale" @change="language"><option value="zh-CN">简体中文</option><option value="en-US">English</option></select></label><a href="/">{{t('orbit.back')}}</a></div></header>
<p class="eyebrow">YOUR SCREEN. YOUR DATA. YOUR CONTROL.</p><h1>{{t('admin.heading')}}</h1><p class="intro">{{t('admin.intro')}}</p><p v-if="error" role="alert" class="notice notice-error">{{t(error)}}</p><p v-if="notice" role="status" class="notice">{{t(notice)}}</p>
<section v-if="!session" class="section login"><h2>{{t('admin.login')}}</h2><p>{{t('admin.keyHint')}}</p><p v-if="!secure" class="notice notice-error">{{t('admin.https')}}</p><form @submit.prevent="login"><label>{{t('admin.key')}}<input type="password" v-model="secret" autocomplete="off" maxlength="128" :disabled="busy||!secure"></label><button :disabled="busy||!secure||!secret">{{t('admin.login')}}</button></form><p class="muted">{{t('admin.bootstrap')}}</p><code>pixora-admin create --name owner --days 90</code></section>
<template v-else><div class="session-line"><span>{{session.name}} · {{t('admin.sessionUntil')}} {{new Date(session.expires_at).toLocaleString(locale)}}</span><button class="secondary" :disabled="busy" @click="logout">{{t('admin.logout')}}</button></div>
<section class="section"><div class="section-head"><div><p class="eyebrow">01 / SCREENS</p><h2>{{t('admin.devices')}}</h2></div><div class="actions"><button class="secondary" :disabled="busy" @click="refresh">{{t('admin.refresh')}}</button><button :disabled="busy" @click="creating=!creating">{{t('admin.new')}}</button></div></div><p class="muted">{{t('admin.inventoryHint')}}</p><div class="filters"><label>{{t('admin.search')}}<input v-model="search" maxlength="80"></label><label>{{t('admin.status')}}<select v-model="filter"><option v-for="state in ['active','expired','revoked','all']" :value="state" :key="state">{{t('admin.'+(state==='expired'?'expiredStatus':state))}}</option></select></label></div>
<div v-if="creating" class="inset"><h3>{{t('admin.new')}}</h3><p>{{t('admin.newHint')}}</p><form @submit.prevent="create"><label>{{t('admin.name')}}<input v-model="newName" maxlength="80" required></label><label>{{t('admin.days')}}<input type="number" v-model.number="days" min="1" max="365" required></label><fieldset><legend>{{t('admin.providers')}}</legend><div class="provider-list"><label v-for="provider in providers" :key="provider" class="check-field"><input type="checkbox" v-model="grants" :value="provider">{{t('provider.'+provider)}}</label></div></fieldset><p class="muted">{{t('admin.newProfileHint')}}</p><button :disabled="busy||!newName.trim()||!grants.length">{{t('admin.create')}}</button></form></div>
<div v-if="pair" class="inset pairing"><h3>{{t('admin.pairing')}}</h3><p>{{t('admin.pairHint')}}</p><canvas ref="canvas" :aria-label="t('admin.pairing')" role="img"/><p>{{t('admin.expires')}} {{new Date(pair.expires_at).toLocaleString(locale)}}</p><details><summary>{{t('admin.pairLink')}}</summary><input readonly :value="pair.url" :aria-label="t('admin.pairLink')" @focus="$event.target.select()"></details><button class="secondary" @click="forgetPair">{{t('admin.hidePair')}}</button></div>
<div class="device-list"><p v-if="!visible.length">{{t('admin.empty')}}</p><article v-for="device in visible" :key="device.id" class="device-row"><label class="device-select"><input type="checkbox" v-model="selected" :value="device.id" :disabled="busy||device.status!=='active'||device.configuration_error" :aria-label="t('admin.select')+' '+device.name"><span><strong>{{device.name}}</strong><small>{{device.id}}</small></span></label><div class="device-meta"><span class="state">{{t('admin.'+(device.status==='expired'?'expiredStatus':device.status))}}</span><span>{{device.providers.join(' · ')}}</span><small>{{t('admin.expires')}} {{new Date(device.expires_at).toLocaleString(locale)}} · {{t('admin.revision')}} {{device.revision??'—'}} · {{t('admin.sessions')}} {{device.sessions}}</small><small v-if="device.configuration_error" role="alert">{{t('admin.configError')}}</small></div><div class="actions"><button class="secondary" :disabled="busy||!device.profile" @click="useProfile(device)">{{t('admin.useProfile')}}</button><button class="secondary" :disabled="busy||device.status!=='active'||device.configuration_error" @click="edit(device)">{{t('admin.edit')}}</button><button class="secondary danger" :disabled="busy||device.status==='revoked'" @click="revokeId=device.id">{{t('admin.revoke')}}</button></div><div v-if="revokeId===device.id" class="confirm"><p>{{t('admin.revokeHint',{name:device.name})}}</p><button class="danger" :disabled="busy" @click="revoke(device)">{{t('admin.confirmRevoke')}}</button><button class="secondary" :disabled="busy" @click="revokeId=null">{{t('admin.cancel')}}</button></div></article></div><button v-if="nextBefore" class="secondary" :disabled="busy" @click="run(()=>load(true))">{{t('admin.more')}}</button>
<div v-if="editing" class="inset"><h3>{{t('admin.edit')}} · {{editing.name}}</h3><label>{{t('admin.name')}}<input v-model="editName" maxlength="80"></label><details><summary>{{t('admin.policy')}}</summary><p>{{t('admin.policyHint')}}</p><textarea v-model="policyText" rows="12" maxlength="16000" :aria-label="t('admin.policy')" spellcheck="false"/></details><div class="actions"><button :disabled="busy||!editName.trim()" @click="saveDevice">{{t('admin.save')}}</button><button class="secondary" :disabled="busy" @click="editing=null">{{t('admin.cancel')}}</button></div></div></section>
<section class="section"><p class="eyebrow">02 / LAYOUT</p><h2>{{t('admin.publish')}}</h2><p>{{t('admin.publishHint')}}</p><fieldset :disabled="busy"><ProfileEditor v-model="draft"/><details><summary>{{t('admin.import')}}</summary><textarea v-model="profileJson" maxlength="16000" rows="7" :aria-label="t('admin.import')" spellcheck="false"/><button type="button" class="secondary" @click="importProfile">{{t('admin.importApply')}}</button></details></fieldset><p>{{t('admin.targetCount',{count:targets.length})}}</p><p v-if="targets.length>20" role="alert">{{t('admin.maxTargets')}}</p><button :disabled="busy||!targets.length||targets.length>20" @click="publish">{{t('admin.publishButton')}}</button></section>
<section class="section"><div class="section-head"><div><p class="eyebrow">03 / ACTIVITY</p><h2>{{t('admin.audit')}}</h2></div><button class="secondary" :disabled="busy" @click="history">{{t('admin.loadAudit')}}</button></div><p class="muted">{{t('admin.auditHint')}}</p><ol class="audit-list"><li v-for="event in events" :key="event.id"><time>{{new Date(event.at).toLocaleString(locale)}}</time><span>{{t('admin.action_'+event.action)}}</span><small>{{event.device_id||'—'}}</small></li></ol></section></template>
<footer><span>{{t('app.principle')}}</span><span>{{t('app.stage')}}</span></footer></main></div></template>
<style scoped>
.admin-page{max-width:1100px;margin:auto;padding:0 max(24px,env(safe-area-inset-left)) 40px;min-height:100dvh}.admin-page h1{font-size:clamp(30px,5vw,48px);letter-spacing:-.04em;margin:12px 0}.intro{max-width:680px;color:var(--muted);line-height:1.8}.eyebrow{font-size:11px;letter-spacing:.14em;color:var(--muted);margin-top:32px}.section{padding:28px 0;border-top:1px solid var(--line);margin-top:24px;line-height:1.7}.section h2{font-size:22px;margin:6px 0 16px}.section h3{font-size:18px}.section-head,.session-line{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}.actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.filters{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin:20px 0}.device-row{display:grid;grid-template-columns:minmax(160px,1fr) minmax(180px,2fr);gap:16px;padding:22px 0;border-top:1px solid var(--line)}.device-row>.actions{grid-column:2}.device-select{display:flex;align-items:start;gap:12px}.device-select input{width:20px;min-height:24px;margin-top:4px;flex-shrink:0}.device-select strong,.device-select small{display:block;overflow-wrap:anywhere}.device-select small,.device-meta small{font-size:12px;color:var(--muted)}.device-meta{display:flex;flex-direction:column;gap:4px;overflow-wrap:anywhere}.state{font-size:12px;text-transform:uppercase;letter-spacing:.06em;color:var(--accent)}.inset{padding:22px;border:1px solid var(--line);margin:24px 0;min-width:0}.provider-list{display:flex;flex-wrap:wrap;gap:12px}.admin-page fieldset{border:0;padding:0;min-width:0;margin:16px 0}.admin-page label{margin:10px 0}.admin-page textarea{width:100%;min-width:0;box-sizing:border-box;font:13px/1.6 monospace;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:8px;padding:12px}.admin-page summary{cursor:pointer;padding:16px 0;min-height:44px}.pairing canvas{max-width:100%;height:auto;background:white}.confirm{grid-column:1/-1;border-left:3px solid var(--danger);padding-left:16px}.confirm button{margin-right:12px}.danger{color:var(--danger)}.session-line{font-size:13px;margin-top:28px}.audit-list{padding:0;list-style:none}.audit-list li{display:flex;gap:16px;flex-wrap:wrap;padding:12px 0;border-bottom:1px solid var(--line);font-size:13px}.audit-list small{overflow-wrap:anywhere}.login{max-width:580px}.login button{margin-top:18px}.login code{display:block;overflow-wrap:anywhere}.language select{min-height:40px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:600px){.admin-page{padding-left:18px;padding-right:18px}.filters,.device-row{grid-template-columns:1fr}.device-row>.actions{grid-column:1}.inset{padding:16px}.app-bar{gap:12px;flex-wrap:wrap}}
</style>
